Definition RK_blk : Z := RK_pixcopy + RK_pixcopy + RK_casc + 1.
Definition RB_blk (w h : Z) : Z := 2 * (RB_pixT (4 * (wpl_of w 1 * h)) + RB_cmapcopy) + RB_casc w h + 2 ^ 17.

